const lessons=[
{title:'认识节点与连线',goal:'看懂数据从哪里来、流向哪里。',body:'ComfyUI 的工作流由节点和连线组成。节点接收输入、执行处理并输出结果；只有类型和用途相符的端口才能连接。不同插件的节点名称与接口可能不同。',example:'把节点想成厨房：装食材、加工、装盘。连线传递的是模型、图像或潜空间等数据，不是文字说明。',diagram:['加载模型','编码提示词 / 准备潜空间','采样','解码','保存图片'],task:'观察你现有文生图工作流：找到加载模型、采样与保存图像节点，沿连线追踪数据。',q:'连线主要表示什么？',options:['数据从一个节点流向另一个节点','两张图只是摆在一起','所有节点都会自动执行'],answer:0,explain:'连线表达节点之间的数据依赖；实际端口类型以节点界面为准。'},
{title:'文生图与图生图',goal:'区分空白起步和基于图片修改。',body:'文生图从文本与初始潜空间出发；图生图通常先读取并编码已有图片，再结合提示词和采样设置进行变化。变化幅度越大越可能偏离原图，具体效果取决于模型与工作流。',example:'想保留人物姿势并换光线：先保留原图作为输入，明确只修改光线，再对照结果调整；不要假定单个参数必然锁定身份。',diagram:['输入图片','编码','结合提示与采样','解码','输出对照'],task:'在自己的图生图流程中找到原图输入和变化幅度设置，保存一张基线结果。',q:'想检查光线改动是否有效，合理的第一步是？',options:['同时更换模型、姿势和场景','保留基线并集中调整光线','只比较文件名'],answer:1,explain:'保留对照并控制主要变量，才更容易判断变化来源。'},
{title:'先写一个可见的故事',goal:'把氛围变成可以拍摄的动作。',body:'从人物、目标、阻碍与结果出发。写清谁在哪里、想做什么、遇到什么，再让动作带来变化。抽象情绪可通过行为、距离、物件和声音表达。',example:'示例：雨夜，少女想把伞留给朋友；末班车进站，她犹豫后将伞放在对方手里，自己走入雨中。',diagram:['局面','目标','阻碍','选择','结果'],task:'用两句话写下你自己的角色、目标和一个可见动作。',q:'哪种描述更容易制作成镜头？',options:['她很孤独、很高级','她把第二个杯子收回柜子','气氛非常感人'],answer:1,explain:'具体行为能让观众观察并推断情绪。'},
{title:'分镜与连续性',goal:'让相邻镜头的人物和道具接得上。',body:'每个镜头记录镜号、景别、起始状态、主要动作、结束状态和声音。跟踪人物位置、视线、持物的手、光线和进出方向。',example:'S01：左侧人物右手拿伞。S02：镜头切近，仍是右手拿伞；递给对方时要出现交接或可理解的省略。',diagram:['S01 起点','动作发生','S01 落点','S02 接续'],task:'为两镜填写：人物位置、道具归属和起止动作；找出一个可能的瞬移。',q:'上一镜右手拿伞，下一镜突然变成左手拿伞，应该？',options:['忽略，因为画面漂亮','检查交接或动作依据','直接判定模型完全不可用'],answer:1,explain:'画面切换可以省略过程，但关键状态变化需要观众能理解。'},
{title:'从首帧到视频',goal:'区分参考图与真正的首帧输入。',body:'首帧图像承担开头的构图和身份信息；视频提示说明主体怎样运动、镜头怎样运动、动作落在哪里。先验证一个主要变化，再增加复杂度。不同节点的首帧、尾帧和参考输入需要按本机实际端口确认。',example:'首帧：角色站在窗边。动作：她缓慢抬手触碰玻璃，镜头固定，最后停在玻璃前；窗帘轻动。',diagram:['确认首帧','选择实际首帧端口','描述动作与镜头','生成短片','逐帧验收'],task:'打开本机工作流，检查目标节点是否确有 first_frame 输入；不要将仅供参考的输入当成首帧。',q:'需要绑定真正的首帧时，应该？',options:['确认工作流中首帧端口并连接图片','随便连接一个参考图端口','只在文件名写首帧'],answer:0,explain:'参考图与首帧是不同职责；以本机节点真实端口和说明为准。'},
{title:'灯光、声音与验收',goal:'把好看拆成可观察的检查项。',body:'先确定主光来自哪里、暗侧是否保留细节，再安排环境反射和冷暖关系。声音分对白、动作声、环境声和配乐；分别检查，而不是用“电影感”代替。',example:'暖灯在人物左侧，窗外是冷光；先生成一张静帧，人物轻微转头后检查阴影是否合理。',diagram:['故事可读','动作连续','光线稳定','试听声音','检查尺寸与时长'],task:'观看完整片段，记录一个具体时间点的问题；未试听就标注声音待检查。',q:'只看过视频首尾帧，可以确认中间动作和声音都合格吗？',options:['可以','不能，需要观看中段并试听','只有画质高就可以'],answer:1,explain:'每项结论都要对应实际检查，首尾帧不能证明中间过程或音轨。'}];
const KEY='creative-course-v1';let done=0,idx=0;try{done=Math.max(0,Math.min(lessons.length,Number(localStorage.getItem(KEY))||0))}catch{} idx=Math.min(done,lessons.length-1);const $=x=>document.getElementById(x);function draw(){const l=lessons[idx];$('steps').innerHTML=lessons.map((x,i)=>`<button class="step ${i===idx?'active':''}" data-i="${i}" ${i>done?'disabled':''}>${String(i+1).padStart(2,'0')} · ${x.title}${i<done?' ✓':''}</button>`).join('');$('lesson').innerHTML=`<article><p class="eyebrow">第 ${idx+1} 关 / 共 ${lessons.length} 关</p><h2>${l.title}</h2><p><b>学完你能：</b>${l.goal}</p><p>${l.body}</p><div class="diagram">${l.diagram.map((x,i)=>`${i?'→':''}<span>${x}</span>`).join('')}</div><h3>看一个例子</h3><div class="example">${l.example}</div><h3>动手观察</h3><p>${l.task}</p><h3>小测：${l.q}</h3><div class="options">${l.options.map((x,i)=>`<label class="option"><input type="radio" name="answer" value="${i}">${x}</label>`).join('')}</div><button class="primary" id="check">提交答案</button><p id="feedback" role="status"></p><button class="primary" id="next" hidden>${idx===lessons.length-1?'完成路线':'进入下一关 →'}</button></article>`;$('check').onclick=()=>{const choice=document.querySelector('input[name=answer]:checked');if(!choice){$('feedback').textContent='请先选择一个答案。';return}if(Number(choice.value)!==l.answer){$('next').hidden=true;$('feedback').textContent='再想一想。'+l.explain;return}$('feedback').textContent='回答正确。'+l.explain;done=Math.max(done,idx+1);try{localStorage.setItem(KEY,done)}catch{}$('next').hidden=false;};$('next').onclick=()=>{if(idx<lessons.length-1){idx++;draw();window.scrollTo(0,0)}else $('feedback').textContent='恭喜完成入门路线。可以返回任一已通过的课程复习。';};document.querySelectorAll('.step').forEach(b=>b.onclick=()=>{idx=Number(b.dataset.i);draw()})} $('reset').onclick=()=>{if(confirm('确定清除本设备上的创作路线进度？')){done=0;idx=0;try{localStorage.removeItem(KEY)}catch{}draw()}};draw();
